<?= view('layouts/app_header', ['user' => $user, 'activePage' => $activePage, 'title' => $title]) ?>
<main id="main" class="main"><div class="pagetitle"><h1>Audit Logs</h1><nav><ol class="breadcrumb"><li class="breadcrumb-item"><a href="<?= esc(site_url('dashboard')) ?>">Dashboard</a></li><li class="breadcrumb-item active">Audit Logs</li></ol></nav></div><section class="section"><div class="card"><div class="card-body"><h5 class="card-title">Filters</h5><form class="row g-2 mb-3" method="get"><div class="col-md-5"><input class="form-control" name="user" placeholder="User name or employee ID" value="<?= esc($filterUser) ?>"></div><div class="col-md-4"><select class="form-select" name="module"><option value="">All activity types</option><?php foreach ($modules as $availableModule): ?><option value="<?= esc((string) $availableModule['module']) ?>" <?= $module === $availableModule['module'] ? 'selected' : '' ?>><?= esc(ucfirst((string) $availableModule['module'])) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><button class="btn btn-primary" type="submit"><i class="bi bi-funnel"></i> Filter</button></div></form><div class="table-responsive"><table class="table table-striped table-hover align-middle"><thead class="table-light"><tr><th>Timestamp</th><th>User</th><th>Department</th><th>Activity</th><th>Description</th><th>IP</th></tr></thead><tbody><?php foreach ($logs as $log): ?><tr><td class="text-nowrap"><?= esc(date('M d, Y h:i A', strtotime((string) $log['created_at']))) ?></td><td><?= esc($log['user_name'] ?: $log['user_id'] ?: 'System') ?></td><td><?= esc($log['department'] ?: '—') ?></td><td><span class="badge bg-secondary"><?= esc(strtoupper($log['action'])) ?></span></td><td><?= esc($log['description'] ?: '—') ?></td><td class="text-muted small"><?= esc($log['ip_address'] ?: '—') ?></td></tr><?php endforeach; ?><?php if ($logs === []): ?><tr><td colspan="6" class="text-center text-muted py-4">No audit logs match your filters.</td></tr><?php endif; ?></tbody></table></div></div></div></section></main>
